#!/usr/bin/env python3
"""Run a command in a PTY, send stepwise input, capture raw output per step.

Usage: pty2.py --cols 80 --rows 24 --steps "KEY1,KEY2,..." --outdir DIR -- cmd args...
KEY tokens: literal text with escapes like \\x1b[A, or named: ENTER, UP, DOWN,
LEFT, RIGHT, ESC, PGUP, PGDN, PLUS, MINUS, TAB, BACKSPACE, SPACE, RESIZE:RxC
Each token is sent as one event; output after each event goes to DIR/stepN.bin
(step0 = initial output before any key).
"""
import os, pty, sys, time, select, argparse, fcntl, termios, struct, signal

NAMED = {
    'ENTER': b'\r', 'UP': b'\x1b[A', 'DOWN': b'\x1b[B', 'RIGHT': b'\x1b[C',
    'LEFT': b'\x1b[D', 'ESC': b'\x1b', 'PGUP': b'\x1b[5~', 'PGDN': b'\x1b[6~',
    'TAB': b'\t', 'BACKSPACE': b'\x7f', 'SPACE': b' ',
}

def token_bytes(tok):
    if tok in NAMED:
        return NAMED[tok]
    if tok.startswith('RESIZE:'):
        return None
    return tok.encode().decode('unicode_escape').encode('latin1')

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--cols', type=int, default=80)
    ap.add_argument('--rows', type=int, default=24)
    ap.add_argument('--outdir', required=True)
    ap.add_argument('--delay', type=float, default=0.25)
    ap.add_argument('--initial-delay', type=float, default=0.5)
    ap.add_argument('--steps', default='q')
    ap.add_argument('--stdin-file', default=None)
    ap.add_argument('cmd', nargs=argparse.REMAINDER)
    args = ap.parse_args()

    cmd = args.cmd
    if cmd and cmd[0] == '--':
        cmd = cmd[1:]

    os.makedirs(args.outdir, exist_ok=True)
    tokens = args.steps.split(',') if args.steps else []

    pid, fd = pty.fork()
    if pid == 0:
        if args.stdin_file is not None:
            r, w = os.pipe()
            data = open(args.stdin_file, 'rb').read()
            os.write(w, data)
            os.close(w)
            os.dup2(r, 0)
        os.execvp(cmd[0], cmd)
        os._exit(127)

    winsz = struct.pack('HHHH', args.rows, args.cols, 0, 0)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, winsz)

    def drain(timeout):
        chunks = []
        end = time.time() + timeout
        while True:
            remaining = end - time.time()
            if remaining <= 0:
                break
            r, _, _ = select.select([fd], [], [], remaining)
            if fd in r:
                try:
                    data = os.read(fd, 65536)
                except OSError:
                    break
                if not data:
                    break
                chunks.append(data)
        return b''.join(chunks)

    with open(os.path.join(args.outdir, 'step0.bin'), 'wb') as f:
        f.write(drain(args.initial_delay))

    for i, tok in enumerate(tokens, 1):
        if tok.startswith('RESIZE:'):
            r_, c_ = tok[7:].split('x')
            winsz = struct.pack('HHHH', int(r_), int(c_), 0, 0)
            fcntl.ioctl(fd, termios.TIOCSWINSZ, winsz)
            os.kill(pid, signal.SIGWINCH)
        else:
            os.write(fd, token_bytes(tok))
        with open(os.path.join(args.outdir, f'step{i}.bin'), 'wb') as f:
            f.write(drain(args.delay))

    try:
        os.close(fd)
    except OSError:
        pass
    try:
        os.kill(pid, signal.SIGKILL)
    except OSError:
        pass
    os.waitpid(pid, 0)

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Minimal VT emulator: feed raw bytes, render screen grid(s).

Usage: vt.py FILE [FILE...]   -- renders cumulative screen per file
       vt.py --all DIR        -- renders step0..N cumulatively
Supports: printable UTF-8 (wcwidth-ish: treats wide chars via unicodedata),
CSI sequences (cursor moves, EL, SGR tracked but only inverse marked),
DECAWM wrap flag, CR/LF. Good enough for FTXUI output analysis.
"""
import sys, unicodedata, re, os

def wcwidth(ch):
    if unicodedata.combining(ch):
        return 0
    return 2 if unicodedata.east_asian_width(ch) in ('W', 'F') else 1

class Term:
    def __init__(self, rows=200, cols=200):
        self.rows, self.cols = rows, cols
        self.grid = [[' ']*cols for _ in range(rows)]
        self.inv = [[False]*cols for _ in range(rows)]
        self.x = self.y = 0
        self.wrap = True
        self.inverse = False
        self.saved = (0, 0)

    def put(self, ch):
        w = wcwidth(ch)
        if w == 0:
            return
        if self.x >= self.cols:
            if self.wrap:
                self.x = 0; self.y = min(self.y+1, self.rows-1)
            else:
                self.x = self.cols - 1
        self.grid[self.y][self.x] = ch
        self.inv[self.y][self.x] = self.inverse
        for i in range(1, w):
            if self.x+i < self.cols:
                self.grid[self.y][self.x+i] = '·'
        self.x += w

    def feed(self, data):
        i = 0
        s = data.decode('utf-8', 'replace')
        # work on bytes for ESC parsing, but utf-8 for text: use incremental approach
        b = data
        text = ''
        def flush_text():
            nonlocal text
            for ch in text:
                if ch == '\r':
                    self.x = 0
                elif ch == '\n':
                    self.y = min(self.y+1, self.rows-1)
                elif ch == '\x07':
                    pass
                elif ch == '\x08':
                    self.x = max(0, self.x-1)
                else:
                    self.put(ch)
            text = ''
        while i < len(b):
            c = b[i]
            if c == 0x1b:
                flush_text()
                if i+1 < len(b) and b[i+1:i+2] == b'[':
                    m = re.match(rb'\x1b\[([0-9;?]*)([@-~])', b[i:])
                    if m:
                        params = m.group(1).decode()
                        final = chr(m.group(2)[0])
                        self.csi(params, final)
                        i += m.end()
                        continue
                    i += 1
                    continue
                elif i+1 < len(b) and b[i+1:i+2] == b'P':
                    # DCS ... ESC\\
                    j = b.find(b'\x1b\\', i)
                    i = (j+2) if j != -1 else len(b)
                    continue
                elif i+1 < len(b) and b[i+1:i+2] in (b'(', b')', b'#', b']'):
                    j = i+2
                    if b[i+1:i+2] == b']':
                        k = b.find(b'\x07', i)
                        k2 = b.find(b'\x1b\\', i)
                        cands = [x for x in (k, k2) if x != -1]
                        i = (min(cands)+1) if cands else len(b)
                    else:
                        i = i+3
                    continue
                else:
                    i += 2
                    continue
            elif c < 0x20 or c == 0x7f:
                text += chr(c)
                i += 1
            else:
                # decode one utf-8 char
                for ln in (1,2,3,4):
                    try:
                        ch = b[i:i+ln].decode('utf-8')
                        text += ch
                        i += ln
                        break
                    except UnicodeDecodeError:
                        continue
                else:
                    i += 1
        flush_text()

    def csi(self, params, final):
        priv = params.startswith('?')
        ps = params.lstrip('?').split(';') if params.lstrip('?') else ['']
        def n(k, d=1):
            try:
                v = int(ps[k]); return v if v else d
            except (ValueError, IndexError):
                return d
        if final == 'A': self.y = max(0, self.y - n(0))
        elif final == 'B': self.y = min(self.rows-1, self.y + n(0))
        elif final == 'C': self.x = min(self.cols-1, self.x + n(0))
        elif final == 'D': self.x = max(0, self.x - n(0))
        elif final == 'E': self.y = min(self.rows-1, self.y + n(0)); self.x = 0
        elif final == 'F': self.y = max(0, self.y - n(0)); self.x = 0
        elif final == 'G': self.x = min(self.cols-1, n(0)-1)
        elif final == 'H' or final == 'f':
            self.y = min(self.rows-1, n(0)-1); self.x = min(self.cols-1, n(1)-1)
        elif final == 'J':
            if n(0, 0) == 2 or params == '':
                if n(0,0) == 2:
                    self.grid = [[' ']*self.cols for _ in range(self.rows)]
                    self.inv = [[False]*self.cols for _ in range(self.rows)]
        elif final == 'K':
            mode = n(0, 0)
            if mode == 0:
                rng = range(self.x, self.cols)
            elif mode == 1:
                rng = range(0, self.x+1)
            else:
                rng = range(0, self.cols)
            for xx in rng:
                self.grid[self.y][xx] = ' '
                self.inv[self.y][xx] = False
        elif final == 'm':
            vals = [int(p) if p else 0 for p in params.split(';')] if params else [0]
            for v in vals:
                if v == 0: self.inverse = False
                elif v == 7: self.inverse = True
                elif v == 27: self.inverse = False
        elif final == 's': self.saved = (self.y, self.x)
        elif final == 'u': self.y, self.x = self.saved
        elif final in 'hl' and priv:
            if '7' in [p for p in params.lstrip('?').split(';')]:
                self.wrap = (final == 'h')

    def render(self, mark_inv=True):
        lines = []
        for row, irow in zip(self.grid, self.inv):
            line = ''
            for ch, iv in zip(row, irow):
                if iv and mark_inv and ch == ' ':
                    line += '█'
                else:
                    line += ch
            lines.append(line.rstrip())
        while lines and not lines[-1]:
            lines.pop()
        return '\n'.join(lines)

def main():
    args = sys.argv[1:]
    rows, cols = 200, 200
    if args and args[0] == '--size':
        rows, cols = int(args[1]), int(args[2]); args = args[3:]
    if args and args[0] == '--all':
        d = args[1]
        files = sorted((f for f in os.listdir(d) if f.startswith('step')), key=lambda f: int(f[4:].split('.')[0]))
        t = Term(rows, cols)
        for f in files:
            t.feed(open(os.path.join(d, f), 'rb').read())
            print(f'===== after {f} (cursor y={t.y} x={t.x}) =====')
            print(t.render())
            print()
    else:
        for f in args:
            t = Term(rows, cols)
            t.feed(open(f, 'rb').read())
            print(f'===== {f} (cursor y={t.y} x={t.x}) =====')
            print(t.render())

if __name__ == '__main__':
    main()

